<?php
declare(strict_types=1);

const PROOF_WINDOW = 90;
const PAGE_SIZE = 20;
const CATEGORIES = ['general','projects','help','showcase','meta'];

$configPath = getenv('OMARCHY_BBS_CONFIG') ?: dirname(__DIR__, 2).'/.config/omarchy-bbs.php';
if (!is_file($configPath)) { http_response_code(503); exit('BBS is not configured.'); }
$config = require $configPath;

function db(): PDO {
  static $pdo; global $config;
  if ($pdo) return $pdo;
  if (($config['driver'] ?? 'mysql') === 'sqlite') {
    $pdo = new PDO('sqlite:'.$config['db_path']);
    @chmod($config['db_path'], 0600);
    $pdo->exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000');
  } else {
    $pdo = new PDO("mysql:host={$config['db_host']};dbname={$config['db_name']};charset=utf8mb4", $config['db_user'], $config['db_pass']);
  }
  $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
  $pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
  $pdo->setAttribute(PDO::ATTR_EMULATE_PREPARES, false);
  return $pdo;
}
function sqlite(): bool { return db()->getAttribute(PDO::ATTR_DRIVER_NAME) === 'sqlite'; }
function addColumn(string $table,string $definition): void { try { db()->exec("ALTER TABLE $table ADD COLUMN $definition"); } catch (PDOException $e) { if (!str_contains(strtolower($e->getMessage()), 'duplicate column')) throw $e; } }
function addIndex(string $statement): void { try { db()->exec($statement); } catch (PDOException $e) { $m=strtolower($e->getMessage());if(!str_contains($m,'already exists')&&!str_contains($m,'duplicate key name'))throw $e; } }
function migrate(): void {
  $id=sqlite()?'INTEGER PRIMARY KEY AUTOINCREMENT':'BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY';
  $big=sqlite()?'INTEGER':'BIGINT UNSIGNED';$text=sqlite()?'TEXT':'MEDIUMTEXT';$defaultNow=sqlite()?"DEFAULT (datetime('now'))":'DEFAULT CURRENT_TIMESTAMP';$engine=sqlite()?'':' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
  $sql=[
    "CREATE TABLE IF NOT EXISTS users (id $id,handle VARCHAR(32) NOT NULL UNIQUE,role VARCHAR(16) NOT NULL DEFAULT 'member',bio_enc $text NULL,mention_notifications INTEGER NOT NULL DEFAULT 1,suspended_until DATETIME NULL,created_at DATETIME NOT NULL $defaultNow)$engine",
    "CREATE TABLE IF NOT EXISTS devices (id VARCHAR(64) PRIMARY KEY,user_id $big NOT NULL,secret_enc TEXT NOT NULL,omarchy_version VARCHAR(80) NOT NULL,created_at DATETIME NOT NULL $defaultNow,last_seen_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS login_nonces (nonce_hash CHAR(64) PRIMARY KEY,expires_at DATETIME NOT NULL)$engine",
    "CREATE TABLE IF NOT EXISTS registrations (id $id,ip_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL $defaultNow)$engine",
    "CREATE TABLE IF NOT EXISTS action_log (id $id,user_id $big NOT NULL,action_kind VARCHAR(24) NOT NULL,created_at DATETIME NOT NULL $defaultNow,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS threads (id $id,user_id $big NOT NULL,category VARCHAR(24) NOT NULL DEFAULT 'general',title_enc TEXT NOT NULL,body_enc $text NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,locked INTEGER NOT NULL DEFAULT 0,edited_at DATETIME NULL,deleted_at DATETIME NULL,created_at DATETIME NOT NULL $defaultNow,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS replies (id $id,thread_id $big NOT NULL,user_id $big NOT NULL,parent_reply_id $big NULL,body_enc $text NOT NULL,edited_at DATETIME NULL,deleted_at DATETIME NULL,created_at DATETIME NOT NULL $defaultNow,FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS thread_likes (thread_id $big NOT NULL,user_id $big NOT NULL,created_at DATETIME NOT NULL $defaultNow,PRIMARY KEY(thread_id,user_id),FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS reply_likes (reply_id $big NOT NULL,user_id $big NOT NULL,created_at DATETIME NOT NULL $defaultNow,PRIMARY KEY(reply_id,user_id),FOREIGN KEY(reply_id) REFERENCES replies(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS thread_reads (user_id $big NOT NULL,thread_id $big NOT NULL,last_read_at DATETIME NOT NULL,PRIMARY KEY(user_id,thread_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS reports (id $id,reporter_id $big NOT NULL,target_kind VARCHAR(16) NOT NULL,target_id $big NOT NULL,reason_enc TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'open',resolved_by $big NULL,created_at DATETIME NOT NULL $defaultNow,resolved_at DATETIME NULL,FOREIGN KEY(reporter_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS category_moderators (category VARCHAR(24) NOT NULL,user_id $big NOT NULL,PRIMARY KEY(category,user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)$engine",
    "CREATE TABLE IF NOT EXISTS mentions (id $id,user_id $big NOT NULL,thread_id $big NOT NULL,reply_id $big NULL,actor_id $big NOT NULL,read_at DATETIME NULL,created_at DATETIME NOT NULL $defaultNow,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE)$engine",
  ]; foreach($sql as $statement)db()->exec($statement);
  foreach(['role VARCHAR(16) NOT NULL DEFAULT \'member\'','bio_enc TEXT NULL','mention_notifications INTEGER NOT NULL DEFAULT 1','suspended_until DATETIME NULL'] as $c)addColumn('users',$c);
  foreach(['pinned INTEGER NOT NULL DEFAULT 0','locked INTEGER NOT NULL DEFAULT 0','edited_at DATETIME NULL','deleted_at DATETIME NULL'] as $c)addColumn('threads',$c);
  foreach(['parent_reply_id '.(sqlite()?'INTEGER':'BIGINT UNSIGNED').' NULL','edited_at DATETIME NULL','deleted_at DATETIME NULL'] as $c)addColumn('replies',$c);
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_threads_category_created ON threads(category,created_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_replies_thread_created ON replies(thread_id,created_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_reports_status_created ON reports(status,created_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_mentions_user_read ON mentions(user_id,read_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_actions_user_kind_created ON action_log(user_id,action_kind,created_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_registrations_ip_created ON registrations(ip_hash,created_at)');
  addIndex('CREATE INDEX '.(sqlite()?'IF NOT EXISTS ':'').'idx_nonces_expires ON login_nonces(expires_at)');
}
function jsonOut(int $status,array $data): never { http_response_code($status);header('Content-Type: application/json');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit; }
function input(): array { $length=(int)($_SERVER['CONTENT_LENGTH']??0);if($length>65536)jsonOut(413,['ok'=>false,'error'=>'Request is too large']);$type=strtolower((string)($_SERVER['CONTENT_TYPE']??''));if(!str_starts_with($type,'application/json'))jsonOut(415,['ok'=>false,'error'=>'JSON content type required']);$v=json_decode(file_get_contents('php://input'),true);if(!is_array($v))jsonOut(400,['ok'=>false,'error'=>'Invalid JSON']);return $v; }
function now(): string { return gmdate('Y-m-d H:i:s'); }
function keyBytes(): string { global $config;$key=hex2bin((string)$config['app_key']);if($key===false||strlen($key)!==32)throw new RuntimeException('Invalid encryption key');return $key; }
function seal(string $plain): string {
  $key=keyBytes();if(function_exists('sodium_crypto_secretbox')){$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return 'sb:'.base64_encode($nonce.sodium_crypto_secretbox($plain,$nonce,$key));}
  $nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag);if($cipher===false)throw new RuntimeException('Encryption failed');return 'gcm:'.base64_encode($nonce.$tag.$cipher);
}
function unseal(?string $value): string {
  if($value===null||$value==='')return '';$key=keyBytes();
  if(str_starts_with($value,'gcm:')){$raw=base64_decode(substr($value,4),true);if($raw===false||strlen($raw)<29)throw new RuntimeException('Invalid encrypted record');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',$key,OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));if($plain===false)throw new RuntimeException('Authentication failed');return $plain;}
  $encoded=str_starts_with($value,'sb:')?substr($value,3):$value;$raw=base64_decode($encoded,true);if($raw===false||!function_exists('sodium_crypto_secretbox_open'))throw new RuntimeException('Unsupported encrypted record');$nonce=substr($raw,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$plain=sodium_crypto_secretbox_open(substr($raw,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$nonce,$key);if($plain===false)throw new RuntimeException('Authentication failed');return $plain;
}
function listArray(array $value): bool {$i=0;foreach($value as $key=>$_){if($key!==$i++)return false;}return true;}
function canonical(mixed $value): string { if($value===[])return '{}';if(is_array($value)){if(listArray($value))$value=array_map(fn($v)=>json_decode(canonical($v),true),$value);else{ksort($value,SORT_STRING);foreach($value as $k=>$v)$value[$k]=json_decode(canonical($v),true);}}return json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); }
function contentPurpose(string $action,array $payload): string { return $action.':'.hash('sha256',canonical($payload)); }
function verify(array $in,string $purpose): array {
  $d=(string)($in['device']??'');$ts=(string)($in['ts']??'');$nonce=(string)($in['nonce']??'');$sig=(string)($in['sig']??'');
  if(!preg_match('/^[A-Za-z0-9_-]{16,64}$/',$d)||!ctype_digit($ts)||abs(time()-(int)$ts)>PROOF_WINDOW||!preg_match('/^[A-Za-z0-9_-]{8,64}$/',$nonce)||!preg_match('/^[a-f0-9]{64}$/',$sig))jsonOut(401,['ok'=>false,'error'=>'Invalid or expired device proof']);
  $q=db()->prepare('SELECT d.user_id,d.secret_enc,u.handle,u.role,u.suspended_until,u.mention_notifications FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=?');$q->execute([$d]);$u=$q->fetch();$secret=$u?hex2bin(unseal($u['secret_enc'])):false;$expected=$secret?hash_hmac('sha256',"$d.$ts.$nonce.$purpose",$secret):'';
  if(!$u||!hash_equals($expected,$sig))jsonOut(401,['ok'=>false,'error'=>'Invalid device proof']);
  try{$q=db()->prepare('INSERT INTO login_nonces(nonce_hash,expires_at) VALUES(?,?)');$q->execute([hash('sha256',$nonce),gmdate('Y-m-d H:i:s',time()+120)]);}catch(PDOException){jsonOut(401,['ok'=>false,'error'=>'Device proof already used']);}
  $u['user_id']=(int)$u['user_id'];$u['device_id']=$d;return $u;
}
function verifiedContent(string $action): array { $in=input();$proof=$in;unset($proof['device'],$proof['ts'],$proof['nonce'],$proof['sig']);return [$in,verify($in,contentPurpose($action,$proof))]; }
function active(array $u): void { if($u['suspended_until']&&strtotime($u['suspended_until'])>time())jsonOut(403,['ok'=>false,'error'=>'This account is suspended until '.$u['suspended_until'].' UTC']); }
function moderator(array $u,string $category=''): bool { if($u['role']==='admin')return true;if($category==='')return false;$q=db()->prepare('SELECT 1 FROM category_moderators WHERE category=? AND user_id=?');$q->execute([$category,$u['user_id']]);return (bool)$q->fetchColumn(); }
function throttle(int $uid,string $kind,int $limit): void {$since=gmdate('Y-m-d H:i:s',time()-600);$q=db()->prepare('SELECT COUNT(*) FROM action_log WHERE user_id=? AND action_kind=? AND created_at>?');$q->execute([$uid,$kind,$since]);if((int)$q->fetchColumn()>=$limit)jsonOut(429,['ok'=>false,'error'=>'Slow down and try again shortly']);db()->prepare('INSERT INTO action_log(user_id,action_kind,created_at) VALUES(?,?,?)')->execute([$uid,$kind,now()]);}
function threadRow(int $id): ?array {$q=db()->prepare('SELECT t.*,u.handle FROM threads t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);return $q->fetch()?:null;}
function reportThreadId(string $kind,int $targetId): int {if($kind==='thread')return $targetId;$q=db()->prepare('SELECT thread_id FROM replies WHERE id=?');$q->execute([$targetId]);return (int)($q->fetchColumn()?:0);}
function mentionUsers(string $body,int $threadId,?int $replyId,array $actor): void {preg_match_all('/(?<![a-z0-9_])@([a-z0-9][a-z0-9_-]{1,30}[a-z0-9])/i',$body,$m);foreach(array_unique(array_map('strtolower',$m[1]??[])) as $handle){$q=db()->prepare('SELECT id FROM users WHERE handle=? AND id<>?');$q->execute([$handle,$actor['user_id']]);$uid=$q->fetchColumn();if($uid){$q=db()->prepare('INSERT INTO mentions(user_id,thread_id,reply_id,actor_id,created_at) VALUES(?,?,?,?,?)');$q->execute([$uid,$threadId,$replyId,$actor['user_id'],now()]);}}}
function likeState(string $kind,int $id,int $uid): array {$table=$kind==='thread'?'thread_likes':'reply_likes';$column=$kind==='thread'?'thread_id':'reply_id';$q=db()->prepare("SELECT COUNT(*) likes,COUNT(CASE WHEN user_id=? THEN 1 END) liked FROM $table WHERE $column=?");$q->execute([$uid,$id]);$r=$q->fetch();return ['likes'=>(int)$r['likes'],'liked'=>(bool)$r['liked']];}
function replyRoot(int $id,int $threadId): int {$seen=[];for($depth=0;$depth<32;$depth++){$q=db()->prepare('SELECT parent_reply_id FROM replies WHERE id=? AND thread_id=?');$q->execute([$id,$threadId]);$row=$q->fetch();if(!$row)jsonOut(400,['ok'=>false,'error'=>'Invalid parent reply']);$parent=$row['parent_reply_id'];if($parent===null)return $id;if(isset($seen[$id]))jsonOut(400,['ok'=>false,'error'=>'Invalid reply tree']);$seen[$id]=true;$id=(int)$parent;}jsonOut(400,['ok'=>false,'error'=>'Reply nesting is too deep']);}
function replyPageForRoot(int $rootId,int $threadId): int {$q=db()->prepare('SELECT COUNT(*) FROM replies WHERE thread_id=? AND parent_reply_id IS NULL AND id<=?');$q->execute([$threadId,$rootId]);return max(1,(int)ceil((int)$q->fetchColumn()/PAGE_SIZE));}

function registerDevice(): never { global $config;$in=input();$device=(string)($in['device_id']??'');$secret=(string)($in['secret']??'');$handle=strtolower(trim((string)($in['handle']??'')));$version=substr(trim((string)($in['omarchy_version']??'')),0,80);if(!preg_match('/^[A-Za-z0-9_-]{16,64}$/',$device)||!preg_match('/^[a-f0-9]{64}$/',$secret)||!preg_match('/^[a-z0-9][a-z0-9_-]{1,30}[a-z0-9]$/',$handle)||$version==='')jsonOut(400,['ok'=>false,'error'=>'Invalid Omarchy identity']);$ip=hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',(string)$config['app_key']);$pdo=db();$q=$pdo->prepare('SELECT COUNT(*) FROM registrations WHERE ip_hash=? AND created_at>?');$q->execute([$ip,gmdate('Y-m-d H:i:s',time()-3600)]);if((int)$q->fetchColumn()>=10)jsonOut(429,['ok'=>false,'error'=>'Too many registrations']);try{$pdo->beginTransaction();$role='member';$q=$pdo->prepare('INSERT INTO users(handle,role,created_at) VALUES(?,?,?)');$q->execute([$handle,$role,now()]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO devices(id,user_id,secret_enc,omarchy_version,created_at) VALUES(?,?,?,?,?)');$q->execute([$device,$uid,seal($secret),$version,now()]);$pdo->prepare('INSERT INTO registrations(ip_hash,created_at) VALUES(?,?)')->execute([$ip,now()]);$pdo->commit();}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();if((string)$e->getCode()==='23000'||str_contains($e->getMessage(),'UNIQUE'))jsonOut(409,['ok'=>false,'error'=>'Username already exists']);throw $e;}jsonOut(201,['ok'=>true,'device_id'=>$device,'handle'=>$handle,'role'=>$role]); }
function apiThreads(): never {[$in,$u]=verifiedContent('threads');$category=strtolower((string)($in['category']??'all'));$query=mb_strtolower(trim((string)($in['query']??'')));$page=max(1,(int)($in['page']??1));$q=db()->prepare('SELECT t.*,u.handle,tr.last_read_at,(SELECT COUNT(*) FROM replies r WHERE r.thread_id=t.id AND r.deleted_at IS NULL) replies,(SELECT MAX(created_at) FROM replies r2 WHERE r2.thread_id=t.id AND r2.deleted_at IS NULL) last_reply,(SELECT COUNT(*) FROM thread_likes tl WHERE tl.thread_id=t.id) likes,(SELECT COUNT(*) FROM thread_likes mine WHERE mine.thread_id=t.id AND mine.user_id=?) liked FROM threads t JOIN users u ON u.id=t.user_id LEFT JOIN thread_reads tr ON tr.user_id=? AND tr.thread_id=t.id WHERE t.deleted_at IS NULL ORDER BY t.pinned DESC,t.id DESC LIMIT 500');$q->execute([$u['user_id'],$u['user_id']]);$rows=$q->fetchAll();$out=[];foreach($rows as $r){$title=unseal($r['title_enc']);$body=unseal($r['body_enc']);if($category!=='all'&&$r['category']!==$category)continue;if($query!==''&&!str_contains(mb_strtolower($title.' '.$body.' '.$r['handle']),$query))continue;$latest=max(strtotime($r['created_at']),strtotime($r['last_reply']?:$r['created_at']));$read=$r['last_read_at'];$out[]=['id'=>(int)$r['id'],'category'=>$r['category'],'title'=>$title,'handle'=>$r['handle'],'created_at'=>$r['created_at'].' UTC','replies'=>(int)$r['replies'],'likes'=>(int)$r['likes'],'liked'=>(bool)$r['liked'],'pinned'=>(bool)$r['pinned'],'locked'=>(bool)$r['locked'],'unread'=>!$read||strtotime($read)<$latest];}$total=count($out);$out=array_slice($out,($page-1)*PAGE_SIZE,PAGE_SIZE);jsonOut(200,['ok'=>true,'handle'=>$u['handle'],'role'=>$u['role'],'categories'=>CATEGORIES,'threads'=>$out,'page'=>$page,'pages'=>max(1,(int)ceil($total/PAGE_SIZE)),'total'=>$total]); }
function apiThread(): never {
  [$in,$u]=verifiedContent('thread');$id=(int)($in['thread_id']??0);$t=threadRow($id);if(!$t||$t['deleted_at'])jsonOut(404,['ok'=>false,'error'=>'Post not found']);
  $q=db()->prepare('SELECT COUNT(*) FROM replies WHERE thread_id=?');$q->execute([$id]);$total=(int)$q->fetchColumn();$q=db()->prepare('SELECT id FROM replies WHERE thread_id=? AND parent_reply_id IS NULL ORDER BY id');$q->execute([$id]);$allRoots=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$pages=max(1,(int)ceil(count($allRoots)/PAGE_SIZE));$requested=(int)($in['reply_page']??0);$page=$requested<1?$pages:min($pages,$requested);$roots=array_slice($allRoots,($page-1)*PAGE_SIZE,PAGE_SIZE);$replies=[];
